import streamlit.components.v1 as components
from visuals import logo

def architecture():
    nodes=[('theo-icon.png','Theo','Scientific model','#7863ff'),('pasqal-icon.png','PASQAL','Neutral-atom hardware','#00bad6'),('qbraid-icon.png','qBraid / IQM','Circuits & measurements','#ab71ff'),('openai.svg','GPT · Claude · Grok','Specialist judgement','#19cba5'),('github.png','GitHub','Specs · evidence · proposed changes','#ffbd72')]
    cards=''.join(f'<div class="tool" style="--accent:{colour}"><img src="{logo(asset)}"><b>{name}</b><span>{purpose}</span></div>' for asset,name,purpose,colour in nodes)
    components.html('''<!doctype html><html><head><style>
    *{box-sizing:border-box}body{margin:0;font-family:Arial,sans-serif;color:#f1f5ff;background:#0c132c;border-radius:22px;overflow:hidden}.os{height:390px;padding:24px;background:radial-gradient(ellipse at 50% 30%,#38479e55,transparent 65%)}
    .entry{text-align:center;color:#a8eaff;font-size:12px;letter-spacing:2px}.core{margin:18px auto;width:320px;text-align:center;padding:20px;border:1px solid #72dfff99;border-radius:18px;box-shadow:0 0 40px #42cfff15;background:#22366455}.core b{font-size:23px;display:block}.core span{display:block;color:#adbee0;font-size:11px;margin-top:9px}.bus{height:28px;position:relative;width:80%;margin:auto;border-top:1px solid #7d87cb66}.bus:before{content:'';position:absolute;left:50%;height:28px;top:-28px;border-left:1px solid #66dcff}
    .tools{display:grid;grid-template-columns:repeat(5,1fr);gap:12px}.tool{display:flex;align-items:center;flex-direction:column;gap:9px;padding:15px 5px;background:#ffffff06;border:1px solid #ffffff18;border-top:3px solid var(--accent);border-radius:12px}.tool img{height:35px;width:50px;object-fit:contain;background:white;padding:5px;border-radius:9px}.tool b{font-size:13px}.tool span{color:#aebfe0;font-size:10px;text-align:center}.records{margin-top:18px;text-align:center;color:#c3d0ec;font-size:11px;letter-spacing:1px}.foot{text-align:center;color:#8e9dc2;font-size:10px;margin-top:13px}
    @media(max-width:700px){.os{height:440px}.tools{gap:5px}.tool b{font-size:11px}.core{width:260px}}
    </style></head><body><div class="os"><div class="entry">QUESTION → TASK RECORD → PLAN → EVIDENCE → HUMAN REVIEW</div><div class="core"><b>QUANTONATION OS</b><span>Prefect orchestration · task registry · bounded tool access</span></div><div class="bus"></div><div class="tools">'''+cards+'''</div><div class="records">OPERATIONAL STATE  /  SCIENTIFIC KNOWLEDGE  /  VERSIONED SPECS</div><div class="foot">Target architecture derived from v2.1 · illustration only</div></div></body></html>''',height=405)